using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using QuestVoiceStreaming;
class QueueTests {
    static int checks;
    static void Check(bool value,string name){if(!value)throw new Exception(name);checks++;}
    static AutoRequest Part(int id,string text,int index=0,int count=1,string whole=null){whole=whole??text;return new AutoRequest {Provider="system",Rate=1.2m,Message=new GameMessage {DialogueId=id.ToString("x24"),Text=text,SegmentIndex=index,SegmentCount=count,TotalBytes=System.Text.Encoding.UTF8.GetByteCount(whole),TextChecksum=AutoSegments.Checksum(whole)}};}
    static async Task Run(){
        await ContinuityChecks();
        Check(SpeechText.Split("你好。请把这封信交给山谷里的守卫，并提醒他注意沿途的危险。之后回来找我。",600).Count>1,"first complete sentence batch should start early");
        var bookMessage=new GameMessage {DialogueId="000000000000000000000001",Source="book",SpeakerName="书籍旁白",SpeakerRace="亡灵",SpeakerSex="male",NpcId="123",QuestTitle="风蚀石板"};
        Check(AutoMetadata.Decode(AutoMetadata.Payload(bookMessage)).Source=="book","book metadata transport roundtrip");
        var bookMap=new Dictionary<string,string>{{"qwen:npc:123","qwen:Cherry"},{"qwen:sex:male","qwen:Ethan"}};
        Check(SpeakerVoiceRouting.Resolve("qwen",bookMessage,bookMap).Identity=="qwen:Ethan","book ignores stale NPC identity");
        var aliases=new Dictionary<string,string>{{"tencent:sex:female","501002"},{"tencent:category:亡灵:male","@general:female"}};
        Check(SpeakerVoiceRouting.Resolve("tencent",new GameMessage {SpeakerSex="male",SpeakerRace="亡灵"},aliases).Identity=="501002","category follows general female");
        bool crossRejected=false;try{SpeakerVoiceRouting.Resolve("tencent",new GameMessage {SpeakerSex="male"},new Dictionary<string,string>{{"tencent:sex:male","qwen:Ethan"}});}catch(ArgumentException){crossRejected=true;}
        Check(crossRejected,"cross-provider configuration rejected");
        var wholeCalls=new List<AutoRequest>();
        var wholeReader=new AutoNarration(new NarrationBudget(),(r,ct)=>{wholeCalls.Add(r);return Task.CompletedTask;},delegate{});
        wholeReader.ResolveVoice=r=>new VoiceSnapshot("qwen:Ethan","clone","test");wholeReader.Enable(true,true);
        wholeReader.Accept(Part(901,"去找布瑞",0,2,"去找布瑞尔的执政官。"));await wholeReader.Work;
        Check(wholeCalls.Count==0,"Qwen waits for verified whole text");
        wholeReader.ResolveVoice=r=>new VoiceSnapshot("qwen:Cherry","clone","test");
        var wholeTail=Part(901,"尔的执政官。",1,2,"去找布瑞尔的执政官。");wholeTail.Rate=2m;
        wholeReader.Accept(wholeTail);await wholeReader.Work;
        Check(wholeCalls.Count==1&&wholeCalls[0].Message.Text=="去找布瑞尔的执政官。","Qwen joins transport fragments before synthesis");
        Check(wholeCalls[0].Message.SegmentCount==1&&wholeCalls[0].Rate==1.2m,"whole request metadata and frozen rate");
        Check(wholeCalls[0].Voice.Identity=="qwen:Ethan","whole voice frozen at first packet");
        wholeReader.Replay(wholeReader.Entries[0]);await wholeReader.Work;
        Check(wholeCalls.Count==2&&wholeCalls[1].Message.Text==wholeCalls[0].Message.Text,"whole replay keeps synthesis cache identity");
        var switchedCalls=new List<AutoRequest>();
        var switched=new AutoNarration(new NarrationBudget(),(r,ct)=>{switchedCalls.Add(r);return Task.CompletedTask;},delegate{});switched.Enable(true,true);
        switched.Replay(wholeReader.Entries[0],"tencent",new VoiceSnapshot("601008","male","test"));await switched.Work;
        Check(switchedCalls.Count==2&&switchedCalls.TrueForAll(r=>r.Provider=="tencent"&&!r.Voice.IsQwen),"replay switches all original transport parts to selected source");
        wholeReader.Accept(Part(902,"未完成",0,2,"未完成台词"));wholeReader.Stop();await wholeReader.Work;
        Check(wholeCalls.Count==2,"stopped partial Qwen never synthesizes");
        wholeReader.Enable(true,true);wholeReader.Accept(Part(903,"错",0,2,"错误"));
        bool rejected=false;try{wholeReader.Accept(Part(903,"字",1,2,"错误"));}catch(System.IO.InvalidDataException){rejected=true;}
        Check(rejected&&wholeCalls.Count==2,"corrupt whole text rejected before any Qwen call");
        string longText=new string('甲',350)+"。"+new string('乙',350)+"。";
        var batches=SpeechText.Split(longText,600);
        Check(batches.Count==2&&batches[0].EndsWith("。")&&String.Join("",batches)==longText,"long text splits only at sentence boundary when available");
        string surrogate=new string('x',599)+"\U0001F600"+new string('y',30);
        batches=SpeechText.Split(surrogate,600);
        Check(String.Join("",batches)==surrogate&&!Char.IsHighSurrogate(batches[0][batches[0].Length-1]),"hard fallback preserves Unicode");
        var calls=new List<string>();var gate=new TaskCompletionSource<bool>();
        var c=new AutoNarration(new NarrationBudget(),async(r,ct)=>{calls.Add(r.Message.Text);if(r.Message.Text=="one")await gate.Task.WaitAsync(ct);},delegate{});
        c.QueueMode=true;c.Enable(true,true);c.Accept(Part(1,"one"));c.Accept(Part(2,"two"));
        Check(c.Entries.Count==2 && c.Entries[1].State=="queued","visible pending FIFO");
        c.Accept(Part(3,"two"));Check(c.Entries.Count==2,"same content pending dedupe");
        gate.SetResult(true);await c.Work;Check(String.Join(",",calls)=="one,two","FIFO order");
        Check(c.Entries[0].State=="completed" && c.Entries[1].Complete,"completed history");
        var entry=c.Entries[1];c.Replay(entry);await c.Work;Check(c.Entries.Count==3 && calls.Count==3 && c.Entries[2].Id!=entry.Id,"manual replay new history identity");
        c.Accept(Part(4,"a",0,2,"ab"));await c.Work;Check(!c.Entries[3].Complete && c.Entries[3].State!="completed","incomplete never complete");
        c.Accept(Part(5,"later"));Check(calls.Count==4,"FIFO waits for missing tail");
        c.Accept(Part(4,"b",1,2,"ab"));await c.Work;Check(String.Join(",",calls)=="one,two,two,a,b,later","FIFO continuation before next dialogue");
        Check(c.Entries[3].Text=="ab" && c.Entries[3].Complete,"assembled history text");
        c.Accept(Part(6,"partial",0,2,"partialtail"));await c.Work;c.Stop();Check(c.Entries[c.Entries.Count-1].State=="interrupted","stop preserves partial history");
        c.Enable(true,true);c.Replay(entry);await c.Work;Check(c.Entries[c.Entries.Count-1].State=="completed","manual replay after pause");
        Check(new AutoNarration(new NarrationBudget(),(r,ct)=>Task.CompletedTask,delegate{}).Entries.Count==0,"session starts empty");
        c=new AutoNarration(new NarrationBudget(),(r,ct)=>Task.CompletedTask,delegate{});c.Enable(true,true);
        for(int i=10;i<230;i++){c.Accept(Part(i,"text"+i));await c.Work;}
        Check(c.Entries.Count==220 && c.Entries[0].Text=="text10","all session history retained until restart");
        Check(AutoSegments.Checksum("abc")==AutoSegments.Checksum("b`d"),"collision fixture");
        var collisionGate=new TaskCompletionSource<bool>();calls.Clear();
        c=new AutoNarration(new NarrationBudget(),async(r,ct)=>{calls.Add(r.Message.Text);if(r.Message.Text=="abc")await collisionGate.Task.WaitAsync(ct);},delegate{});
        c.Enable(true,true);c.Accept(Part(250,"abc"));c.Accept(Part(251,"b`d"));collisionGate.TrySetResult(true);await c.Work;
        Check(calls.Count==2 && calls[1]=="b`d","checksum collision is not deduplication");
        var duplicateGate=new TaskCompletionSource<bool>();calls.Clear();
        c=new AutoNarration(new NarrationBudget(),async(r,ct)=>{calls.Add(r.Message.Text);if(r.Message.Text=="a")await duplicateGate.Task.WaitAsync(ct);},delegate{});
        c.Enable(true,true);c.Accept(Part(260,"a",0,2,"abc"));c.Accept(Part(260,"bc",1,2,"abc"));
        c.Accept(Part(261,"a",0,2,"abc"));Check(calls.Count==1,"candidate does not cancel or synthesize before whole text");
        c.Accept(Part(261,"bc",1,2,"abc"));Check(c.Entries.Count==1,"exact whole duplicate reuses active entry");
        duplicateGate.SetResult(true);await c.Work;Check(calls.Count==2,"duplicate causes no extra segment request");
        var multipartGate=new TaskCompletionSource<bool>();calls.Clear();
        c=new AutoNarration(new NarrationBudget(),async(r,ct)=>{calls.Add(r.Message.Text);if(r.Message.Text=="abc")await multipartGate.Task.WaitAsync(ct);},delegate{});
        c.Enable(true,true);c.Accept(Part(270,"abc"));c.Accept(Part(271,"b",0,2,"b`d"));c.Accept(Part(271,"`d",1,2,"b`d"));
        multipartGate.TrySetResult(true);await c.Work;Check(String.Join(",",calls)=="abc,b,`d","multipart collision applies interrupt only after exact text known");
        var interleaveGate=new TaskCompletionSource<bool>();calls.Clear();
        c=new AutoNarration(new NarrationBudget(),async(r,ct)=>{calls.Add(r.Message.Text);if(r.Message.Text=="a")await interleaveGate.Task.WaitAsync(ct);},delegate{});
        c.Enable(true,true);c.Accept(Part(280,"a",0,2,"abc"));c.Accept(Part(281,"ab",0,2,"abc"));c.Accept(Part(281,"c",1,2,"abc"));
        Check(calls.Count==1,"complete candidate waits for incomplete original");
        c.Accept(Part(280,"bc",1,2,"abc"));interleaveGate.SetResult(true);await c.Work;
        Check(c.Entries.Count==1 && calls.Count==2,"interleaved duplicate resolved by exact text");
        var held=new TaskCompletionSource<bool>();CancellationToken token=CancellationToken.None;calls.Clear();
        c=new AutoNarration(new NarrationBudget(),async(r,ct)=>{calls.Add(r.Message.Text);token=ct;await held.Task.WaitAsync(ct);},delegate{});
        c.QueueMode=true;c.Enable(true,true);c.Accept(Part(300,"held"));
        for(int i=301;i<317;i++)c.Accept(Part(i,"pending"+i));
        Check(c.Entries[16].State=="failed" && calls.Count==1,"bounded FIFO records explicit overflow");
        c.Stop();await c.Work;Check(token.IsCancellationRequested && c.Entries[0].State=="interrupted" && c.Entries[1].State=="interrupted","stop cancels and retains queue history");
        var voiceGate=new TaskCompletionSource<bool>();
        c=new AutoNarration(new NarrationBudget(),async(r,ct)=>await voiceGate.Task.WaitAsync(ct),delegate{});
        c.QueueMode=true;c.Enable(true,true);
        var man=Part(310,"same words");man.Provider="tencent";man.Message.SpeakerSex="male";
        var woman=Part(311,"same words");woman.Provider="tencent";woman.Message.SpeakerSex="female";
        c.Accept(man);c.Accept(woman);
        Check(c.Entries.Count==2,"male and female identical text must not deduplicate");
        voiceGate.SetResult(true);await c.Work;
        Check(c.Entries[0].Voice.Identity=="601008" && c.Entries[1].Voice.Identity=="501002","verified Tencent male/female defaults");
        Check(SpeakerVoiceRouting.Resolve("tencent",new GameMessage()).Identity=="601008","unknown sex default");
        var cloneMap=new Dictionary<string,string>{{"qwen:category:亡灵:male","qwen:Ethan"}};
        var cloned=SpeakerVoiceRouting.Resolve("qwen",new GameMessage {SpeakerRace="亡灵",SpeakerSex="male"},cloneMap);
        Check(cloned.IsQwen && cloned.CloudVoice=="Ethan","Qwen category voice routing");
        Check(!SpeakerVoiceRouting.Resolve("tencent",new GameMessage {SpeakerRace="亡灵",SpeakerSex="female"},cloneMap).IsQwen,"female unchanged");
        Check(!SpeakerVoiceRouting.Resolve("tencent",new GameMessage {SpeakerSex="male"},cloneMap).IsQwen,"unknown race unchanged");
        Check(!SpeakerVoiceRouting.Resolve("system",new GameMessage {SpeakerRace="亡灵",SpeakerSex="male"},cloneMap).IsQwen,"system never calls clone");
        var map=new Dictionary<string,string>{{"tencent:npc:42","1001"},{"tencent:category:亡灵:female","1002"},{"tencent:sex:female","1003"}};
        var identity=new GameMessage {NpcId="42",SpeakerRace="亡灵",SpeakerSex="female"};
        Check(SpeakerVoiceRouting.Resolve("tencent",identity,map).Identity=="1001","explicit NPC precedence");
        identity.NpcId=null;Check(SpeakerVoiceRouting.Resolve("tencent",identity,map).Identity=="1002","race and gender configuration");
        identity.SpeakerRace=null;Check(SpeakerVoiceRouting.Resolve("tencent",identity,map).Identity=="1003","generic gender configuration");
        Check(SpeakerVoiceRouting.Categories.Count==24,"24 race/reserved/default configuration slots");
        var categoryKeys=new HashSet<string>();foreach(var category in SpeakerVoiceRouting.Categories)Check(categoryKeys.Add(category.Key),"unique category key");
        var fallbacks=new Dictionary<string,string>{{"tencent:default","1009"},{"tencent:reserved:child:female","1010"},{"tencent:reserved:neutral","1011"}};
        Check(SpeakerVoiceRouting.Resolve("tencent",new GameMessage {SpeakerSex="female"},fallbacks).Identity=="501002","known gender uses generic before unknown default");
        Check(SpeakerVoiceRouting.Resolve("tencent",new GameMessage(),fallbacks).Identity=="1009","unknown uses configured default, never reserved slots");
        fallbacks["tencent:category:天裔:female"]="601008";
        Check(SpeakerVoiceRouting.Resolve("tencent",new GameMessage {SpeakerRace="天裔",SpeakerSex="female"},fallbacks).Identity=="601008","tianyi override");
        fallbacks.Remove("tencent:category:天裔:female");
        Check(SpeakerVoiceRouting.Resolve("tencent",new GameMessage {SpeakerRace="天裔",SpeakerSex="female"},fallbacks).Identity=="501002","removed override follows gender");
        var installed=new[]{"local-female\tfemale\tzh-CN","local-male\tmale\tzh-TW"};
        identity.SpeakerSex="male";
        Check(SpeakerVoiceRouting.Resolve("system",identity,null,installed).Identity=="local-male","installed gender over default culture");
        Check(SpeakerVoiceRouting.Resolve("system",identity,null,new[]{installed[0]}).Status.Contains("回退"),"missing gender reports fallback");
        Check(SpeakerVoiceRouting.Resolve("system",identity).Identity=="","no installed voice never switches cloud");
        var snapshots=new List<string>();string selected="local-male";
        c=new AutoNarration(new NarrationBudget(),(r,ct)=>{snapshots.Add(r.Provider+":"+r.Voice.Identity+":"+r.Rate);return Task.CompletedTask;},delegate{});
        c.ResolveVoice=r=>new VoiceSnapshot(selected,selected,"test");c.Enable(true,true);
        var head=Part(312,"a",0,2,"ab");c.Accept(head);await c.Work;
        selected="local-female";head.Provider="tencent";head.Voice=new VoiceSnapshot("bad","bad","bad");head.Message.Text="mutated";
        var tail=Part(312,"b",1,2,"ab");tail.Provider="tencent";tail.Rate=2m;c.Accept(tail);await c.Work;
        Check(c.Entries[0].Parts[0].Message.Text=="a","admitted request detached from caller mutation");
        c.Replay(c.Entries[0]);await c.Work;
        Check(snapshots.Count==4 && snapshots.TrueForAll(s=>s=="system:local-male:1.2"),"system segmented playback and replay freeze actual voice/provider/rate");
        snapshots.Clear();c=new AutoNarration(new NarrationBudget(),(r,ct)=>{snapshots.Add(r.Voice.Identity);return Task.CompletedTask;},delegate{});c.Enable(true,true);
        var cloudHead=Part(313,"a",0,2,"ab");cloudHead.Provider="tencent";cloudHead.Message.SpeakerSex="female";c.Accept(cloudHead);await c.Work;
        var cloudTail=Part(313,"b",1,2,"ab");cloudTail.Provider="tencent";cloudTail.Message.SpeakerSex="female";c.Accept(cloudTail);await c.Work;
        c.ResolveVoice=r=>new VoiceSnapshot("601008","changed","changed");c.Replay(c.Entries[0]);await c.Work;
        Check(snapshots.Count==4 && snapshots.TrueForAll(s=>s=="501002"),"Tencent segmented replay preserves female snapshot");
        var queueVoiceGate=new TaskCompletionSource<bool>();selected="local-male";snapshots.Clear();
        c=new AutoNarration(new NarrationBudget(),async(r,ct)=>{snapshots.Add(r.Voice.Identity);if(r.Message.Text=="hold")await queueVoiceGate.Task.WaitAsync(ct);},delegate{});
        c.ResolveVoice=r=>new VoiceSnapshot(selected,selected,"test");c.QueueMode=true;c.Enable(true,true);
        c.Accept(Part(314,"hold"));c.Accept(Part(315,"queued"));selected="local-female";queueVoiceGate.SetResult(true);await c.Work;
        Check(snapshots.Count==2 && snapshots[1]=="local-male","queued system entry fixed before playback starts");
        snapshots.Clear();c=new AutoNarration(new NarrationBudget(),(r,ct)=>{snapshots.Add(r.Voice.Identity);return Task.CompletedTask;},delegate{});
        c.ResolveVoice=r=>new VoiceSnapshot(selected,selected,"test");c.Enable(true,true);
        selected="first";c.Accept(Part(316,"same"));await c.Work;selected="second";c.Accept(Part(316,"same"));await c.Work;
        Check(snapshots.Count==2 && snapshots[1]=="second","same wire dialogue reopens with new actual voice");
        var changedProvider=Part(316,"same");changedProvider.Provider="tencent";c.Accept(changedProvider);await c.Work;
        Check(snapshots.Count==3,"same wire dialogue reopens with new provider");
        c.Accept(Part(317,"a",0,2,"ab"));await c.Work;c.Accept(Part(317,"b",1,2,"ab"));await c.Work;
        selected="third";c.Accept(Part(317,"a",0,2,"ab"));await c.Work;selected="fourth";c.Accept(Part(317,"b",1,2,"ab"));await c.Work;
        Check(snapshots.Count==7 && snapshots[5]=="third" && snapshots[6]=="third","reopened segmented continuation finds frozen new entry");
        string provider=null;decimal rate=0;
        c=new AutoNarration(new NarrationBudget(),(r,ct)=>{provider=r.Provider;rate=r.Rate;return Task.CompletedTask;},delegate{});
        c.Enable(true,true);var original=Part(320,"voice");original.Provider="tencent";original.Rate=1.7m;c.Accept(original);await c.Work;
        c.Replay(c.Entries[0]);await c.Work;Check(provider=="tencent" && rate==1.7m,"replay preserves voice cache identity");
        c.Stop();await c.Work;c.ClearHistory();Check(c.Entries.Count==0,"clear removes history");
        c.Enable(true,true);c.Accept(original);await c.Work;Check(c.Entries.Count==1,"clear resets read suppression for identical dialogue");
        var clearGate=new TaskCompletionSource<bool>();
        c=new AutoNarration(new NarrationBudget(),async(r,ct)=>await clearGate.Task.WaitAsync(ct),delegate{});c.Enable(true,true);
        c.Accept(Part(329,"active"));bool busyRejected=false;
        try{c.ClearHistory();}catch(InvalidOperationException){busyRejected=true;}
        Check(busyRejected,"cannot clear before in-flight playback ends");
        c.Stop();await c.Work;c.ClearHistory();Check(c.Entries.Count==0,"cancel then clear active history");
        c=new AutoNarration(new NarrationBudget(),(r,ct)=>{throw new InvalidOperationException("provider failed");},delegate{});
        c.Enable(true,true);c.Accept(Part(330,"failure"));await c.Work;Check(c.Entries[0].State=="failed" && !c.Enabled,"failure visible and disabled");
        int isolated=0;
        c=new AutoNarration(new NarrationBudget(),(r,ct)=>{isolated++;return Task.CompletedTask;},delegate{});c.Enable(true,true);
        var gameA=Part(400,"same");gameA.Message.Session="game-a";
        var gameB=Part(400,"same");gameB.Message.Session="game-b";
        c.Accept(gameA);await c.Work;c.Accept(gameB);await c.Work;
        Check(isolated==2 && c.Entries.Count==2,"same dialogue id from different games is not suppressed");
        var startA=Part(401,"a",0,2,"ab");startA.Message.Session="game-a";
        var wrongTail=Part(401,"b",1,2,"ab");wrongTail.Message.Session="game-b";
        c.Accept(startA);await c.Work;c.Accept(wrongTail);await c.Work;
        Check(!c.Entries[c.Entries.Count-1].Complete,"other game's continuation cannot complete dialogue");
        wrongTail.Message.Session="game-a";c.Accept(wrongTail);await c.Work;
        Check(c.Entries[c.Entries.Count-1].Complete,"correct game's continuation completes dialogue");
        Console.WriteLine("PASS queue/history: "+checks+" assertions, no cloud");
    }
    static async Task ContinuityChecks(){
        var npcGate=new TaskCompletionSource<bool>();var npcOrder=new List<string>();CancellationToken npcToken=default(CancellationToken);
        var npcQueue=new AutoNarration(new NarrationBudget(),async(r,ct)=>{npcOrder.Add(r.Message.Text);if(r.Message.Text=="first NPC quest"){npcToken=ct;await npcGate.Task.WaitAsync(ct);}},delegate{});
        npcQueue.Enable(true,true);
        for(int i=0;i<3;i++){
            var task=Part(900+i,i==0?"first NPC quest":"NPC quest "+i);
            task.Message.Source="npc";task.Message.NpcId="42";task.Message.SpeakerName="同一NPC";task.Message.QuestTitle="任务"+i;
            npcQueue.Accept(task);
        }
        Check(!npcToken.IsCancellationRequested && npcOrder.Count==1 && npcQueue.Entries[2].State=="queued","multiple quests from the same NPC must queue without requiring a turn-in");
        npcGate.SetResult(true);await npcQueue.Work;
        Check(String.Join("|",npcOrder)=="first NPC quest|NPC quest 1|NPC quest 2","same NPC quest order retained");
        npcGate=new TaskCompletionSource<bool>();npcOrder.Clear();
        npcQueue=new AutoNarration(new NarrationBudget(),async(r,ct)=>{npcOrder.Add(r.Message.Text);if(r.Message.Text=="first NPC quest"){npcToken=ct;await npcGate.Task.WaitAsync(ct);}},delegate{});npcQueue.Enable(true,true);
        var firstNpc=Part(910,"first NPC quest");firstNpc.Message.Source="npc";firstNpc.Message.NpcId="42";firstNpc.Message.QuestTitle="任务A";npcQueue.Accept(firstNpc);
        var otherNpc=Part(911,"other NPC quest");otherNpc.Message.Source="npc";otherNpc.Message.NpcId="43";otherNpc.Message.QuestTitle="任务B";npcQueue.Accept(otherNpc);
        await npcQueue.Work;
        Check(npcToken.IsCancellationRequested && npcQueue.Entries[0].State=="interrupted","different NPC does not inherit same-NPC queue protection");
        string story="你好。请把这封信交给山谷里的守卫，并提醒他注意沿途的危险。之后回来找我。";
        var batches=SpeechText.Split(story,600);
        Check(batches[0]=="你好。请把这封信交给山谷里的守卫，并提醒他注意沿途的危险。","short first sentence joins next complete sentence");
        Check(String.Join("",batches)==story,"sentence batching preserves exact text");
        string quote=new string('中',25)+"。”然后";
        Check(SpeechText.Split(quote,600)[0].EndsWith("。”"),"closing quote stays with sentence");
        foreach(string source in new[]{"turnin","turnin-m","npc-m","quest-m","book-m"}){
            var m=Part(810,story).Message;m.Source=source;
            var copy=AutoMetadata.Decode(AutoMetadata.Payload(m));
            Check(copy.Source==source && AutoMetadata.Manual(copy)==source.EndsWith("-m"),"play intent metadata "+source);
        }
        var now=new DateTime(2026,9,27,0,0,0,DateTimeKind.Utc);int calls=0;
        var c=new AutoNarration(new NarrationBudget(),(r,ct)=>{calls++;return Task.CompletedTask;},delegate{});
        c.UtcNow=()=>now;c.Enable(true,true);
        c.Accept(Part(820,"same speech"));await c.Work;
        now=now.AddSeconds(119);c.Accept(Part(821,"same speech"));await c.Work;
        Check(calls==1 && c.Entries.Count==1,"automatic duplicate suppressed before 120 seconds");
        now=now.AddSeconds(1);c.Accept(Part(822,"same speech"));await c.Work;
        Check(calls==2,"automatic replay allowed at 120 seconds");
        var manual=Part(823,"same speech");manual.Message.Source="npc-m";c.Accept(manual);await c.Work;
        Check(calls==3,"manual game playback bypasses cooldown");
        c.Replay(c.Entries[0]);await c.Work;Check(calls==4,"history replay bypasses cooldown");
        c.Accept(Part(824,"same ",0,2,"same speech"));c.Accept(Part(824,"speech",1,2,"same speech"));await c.Work;
        Check(calls==4,"multipart cooldown verifies full assembled text");
        var gate=new TaskCompletionSource<bool>();var played=new List<string>();CancellationToken firstToken=default(CancellationToken);
        c=new AutoNarration(new NarrationBudget(),async(r,ct)=>{played.Add(r.Message.Text);if(r.Message.Text=="reward"){firstToken=ct;await gate.Task.WaitAsync(ct);}},delegate{});c.Enable(true,true);
        var reward=Part(830,"reward");reward.Message.Source="turnin";c.Accept(reward);
        var next=Part(831,"next quest");next.Message.Source="npc";c.Accept(next);
        var nextAgain=Part(832,"another quest");nextAgain.Message.Source="npc";c.Accept(nextAgain);
        Check(!firstToken.IsCancellationRequested && played.Count==1 && c.Entries[1].State=="queued","turn-in protects current speech and queues subsequent pages");
        gate.SetResult(true);await c.Work;
        Check(String.Join("|",played)=="reward|next quest|another quest","turn-in chain plays in order");
        gate=new TaskCompletionSource<bool>();c.Accept(Part(833,"ordinary hold"));await c.Work;
        reward=Part(834,"reward");reward.Message.Source="turnin-m";c.Accept(reward);next=Part(835,"pending");next.Message.Source="npc";c.Accept(next);
        c.Stop();await c.Work;Check(firstToken.IsCancellationRequested && c.Entries[c.Entries.Count-1].State=="interrupted","explicit stop clears protected chain");
        c.Enable(true,true);gate.SetResult(true);reward=Part(836,"reward");reward.Message.Source="turnin";
        int before=played.Count;c.Accept(reward);await c.Work;
        // Earlier reward completed, so test incomplete retry with a different text.
        var retryGate=new TaskCompletionSource<bool>();calls=0;
        c=new AutoNarration(new NarrationBudget(),async(r,ct)=>{calls++;if(calls==1)await retryGate.Task.WaitAsync(ct);},delegate{});c.Enable(true,true);
        c.Accept(Part(840,"unfinished"));c.Stop();await c.Work;c.Enable(true,true);c.Accept(Part(841,"unfinished"));await c.Work;
        Check(calls==2,"interrupted speech is not remembered as completed");
    }
    static int Main(){try{Run().GetAwaiter().GetResult();return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
